int main(void) {
    unsigned int n;
    int q;
    if (scanf("%u %d", &n, &q) != 2) return 0;

    for (int i = 0; i < q; i++) {
        int op, k;
        if (scanf("%d %d", &op, &k) != 2) break;

        switch (op) {
            case 1:
                n |= (1U << k);
                break;
            case 2:
                n &= ~(1U << k);
                break;
            case 3:
                n ^= (1U << k);
                break;
            case 4:
                printf("%u\n", (n >> k) & 1U);
                break;
            default:
                break;
        }
    }

    printf("%u\n", n);
    return 0;
}

