#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 3100000
#define BITS 30

static int trie[MAX_NODES][2];
static int node_count = 1;

static void insert(int val) {
    int curr = 0;
    for (int i = BITS - 1; i >= 0; i--) {
        int b = (val >> i) & 1;
        if (!trie[curr][b]) {
            trie[curr][b] = node_count++;
        }
        curr = trie[curr][b];
    }
}

static int query_max_xor(int val) {
    int curr = 0;
    int max_xor = 0;
    for (int i = BITS - 1; i >= 0; i--) {
        int b = (val >> i) & 1;
        int opp = 1 - b;
        if (trie[curr][opp]) {
            max_xor |= (1 << i);
            curr = trie[curr][opp];
        } else {
            curr = trie[curr][b];
        }
    }
    return max_xor;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *nums = (int *)malloc(n * sizeof(int));
    if (!nums) return 1;

    for (int i = 0; i < n; i++) {
        scanf("%d", &nums[i]);
    }

    insert(nums[0]);
    int best = 0;
    for (int i = 1; i < n; i++) {
        int candidate = query_max_xor(nums[i]);
        if (candidate > best) {
            best = candidate;
        }
        insert(nums[i]);
    }

    printf("%d\n", best);
    free(nums);
    return 0;
}
